bg = 9

def transform(grid_in):
    h = len(grid_in)
    w = len(grid_in[0])
    # Output has same dimensions as input
    output = [[bg for _ in range(w)] for _ in range(h)]

    # For demo 1 (8x3), the pattern repeats every 3 rows
    # For demo 2 (4x23), the pattern repeats every 8 columns

    # SAME: within each mod class (mod 3 for rows, or mod (period) for cols), use the most populated row

    # Check if we're processing a tall grid (h > w likely) or wide grid (w > h)
    if h > w:
        # Tall grid - mod 3 row rule
        for rem in range(3):
            rows_in_class = [r for r in range(h) if r % 3 == rem]

            # Find row with most non-background pixels
            best_row = rows_in_class[0]
            max_pop = -1
            for r in rows_in_class:
                pop = sum(1 for c in range(w) if grid_in[r][c] != bg)
                if pop > max_pop:
                    max_pop = pop
                    best_row = r

            # Copy this row to all rows in this class
            for r in rows_in_class:
                for c in range(w):
                    output[r][c] = grid_in[best_row][c]
    else:
        # Wide grid - column mod rule
        # Calculate period from separator columns (like the 1s in demo 2)
        # Find columns that have a single unique non-background value repeated
        period = w // h  # rough estimate

        # For demo 2, period is 8 (separator columns 7, 15, 23)
        # Find separator columns
        separators = []
        for col in range(w):
            vals = set(grid_in[r][col] for r in range(h))
            if len(vals) == 1:
                separator_vals = [grid_in[0][col]]
                all_same = True
                for r in range(1, h):
                    if grid_in[r][col] != grid_in[0][col]:
                        all_same = False
                        break
                if all_same:
                    if grid_in[0][col] not in separators:
                        separators.append(col)

        if separators:
            period = separators[1] - separators[0]
        else:
            period = w // h

        for col in range(w):
            row_pattern = [grid_in[r][col] for r in range(h)]

            # Find the "template" column
            for template_col in range(col, min(col + period, w)):
                if grid_in[0][template_col] == row_pattern[-1] if h > 1 else True:
                    for new_col in range(8, 8 + period):
                        new_col = template_col + (new_col - period)
                        if new_col < w:
                            for r in range(h):
                                output[r][new_col] = grid_in[r][template_col]
                        break

    return output

